import React from 'react';
import { FiDownload, FiEye, FiPlus } from 'react-icons/fi';
import { FaThumbtack } from 'react-icons/fa';

export default function DatasetCard({ index }) {
  return (
    <div className="grid grid-cols-6 items-center gap-4 p-4 border-b border-gray-200 dark:border-gray-700 text-sm hover:bg-gray-100 dark:hover:bg-gray-800 transition-all">
      <div className="col-span-2">
        <div className="flex items-center gap-2">
          <FaThumbtack className="text-yellow-500" />
          <div>
            <p className="font-semibold text-gray-800 dark:text-white">Example Dataset {index + 1}</p>
            <p className="text-xs text-gray-500 dark:text-gray-400">This is a short description</p>
          </div>
        </div>
      </div>
      <div className="text-gray-700 dark:text-gray-300">Source Org</div>
      <div className="text-gray-700 dark:text-gray-300">Jun 1, 2023</div>
      <div className="text-gray-700 dark:text-gray-300">247</div>
      <div className="flex gap-2 text-gray-600 dark:text-gray-300">
        <FiPlus className="cursor-pointer hover:text-blue-500" />
        <FiEye className="cursor-pointer hover:text-blue-500" />
        <FiDownload className="cursor-pointer hover:text-blue-500" />
      </div>
    </div>
  );
}
